mapper.select:
SELECT 
FROM t_user u
WHERE u.id = #{id}

mapper.update:
UPDATE t_user
SET `status` = #{status},
    token_version = token_version + 1,
    updated_at = #{now}
WHERE id = #{id}

UPDATE t_user SET nickname = #{nickname},
`identity` = NULL, `identity` = #{identity},
crops = #{crops}, avatar_url = NULL, updated_at = #{now} WHERE id = #{id}

mapper.select:
SELECT id, user_id, `mode`, image_url, `status`, top_name, confidence, severity, fail_reason, model, fallback,
       deleted, created_at
FROM t_recognition
WHERE user_id = #{userId}
ORDER BY created_at DESC, id DESC
LIMIT #{offset}, #{size}

SELECT id, user_id, image_url, deleted
FROM t_recognition
WHERE id = #{id}
